/**  应用支持的语言 */
export type Locale = "en" | "zh-CN";

/**  模型分类：同时是 `models/` 下的一级目录名 */
export type ModelCategory = 
/**  `FunASR Nano` 系：`funasr-nano` */
"funasr_nano" | 
/**  `Qwen3-ASR` 系：`qwen3-asr` */
"qwen3_asr" | 
/**  `SenseVoice` 系：`sense-voice` */
"sense_voice";

/**  前端展示的模型条目：状态由后端实时判定，前端不做本地推断 */
export type ModelEntry = {
	/**  模型 id（与 `ModelSpec::id` 一一对应） */
	id: string,
	/**  所属分类 */
	category: ModelCategory,
	/**  展示名 */
	display_name: string,
	/**  压缩包字节数（展示用，均小于 4GB，见 `registry_sizes_fit_u32`） */
	tarball_bytes: number,
	/**  必需文件字节数之和（展示用） */
	required_bytes: number,
	/**  本机状态 */
	status: ModelStatus,
	/**  模型目录绝对路径（`Missing` 时为 `None`） */
	local_path: string | null,
	/**  发布页地址（“前往下载页”按钮用） */
	page_url: string,
};

/**  模型在本机的就绪状态 */
export type ModelStatus = 
/**  目标目录无任何必需文件 */
"missing" | 
/**  部分必需文件缺失或大小不符 */
"partial" | 
/**  全部必需文件齐全且大小一致 */
"ready" | 
/**  后端正在下载或解压 */
"downloading";

/**  结束录制的回执：前端据此展示文件名与时长，再调转写命令 */
export type RecordResult = {
	/**  存档绝对路径 */
	path: string,
	/**  文件名（展示用） */
	file_name: string,
	/**  录制秒数 */
	seconds: number | null,
};

/**  服务状态：启动中与运行中互斥，同一时刻只加载一个模型 */
export type ServiceState = 
/**  未加载任何模型 */
"stopped" | 
/**  正在加载模型（阻塞式加载，期间拒绝重复启动） */
"starting" | 
/**  已加载，可接受转写 */
"running";

/**  服务状态快照：前端据此渲染徽标与按钮可用性 */
export type ServiceStatus = {
	/**  当前状态 */
	state: ServiceState,
	/**  已加载（或正在加载）的模型 id */
	model_id: string | null,
	/**  已加载模型的展示名 */
	display_name: string | null,
	/**  模型加载耗时毫秒（仅运行中有效） */
	load_ms: number | null,
};

/**  运行平台信息：经 `tauri-plugin-os` 采集，全字段必填，前端逐行展示 */
export type SystemInfo = {
	/**  操作系统平台（如 `linux` / `windows` / `macos`） */
	platform: string,
	/**  操作系统版本 */
	os_version: string,
	/**  系统架构（如 `x86_64`） */
	arch: string,
	/**  主机名 */
	hostname: string,
};

/**  文件转写结果：文本 + 音频时长 + 推理耗时，前端直接回显 */
export type TranscribeResult = {
	/**  识别文本（空音频或静音时为空字符串，不算失败） */
	text: string,
	/**  音频时长秒 */
	audio_sec: number | null,
	/**  推理耗时毫秒 */
	infer_ms: number,
};

/**  可用的更新信息：只含前端展示所需字段，插件的 `Update` 句柄不出命令边界 */
export type UpdateInfo = {
	/**  远端版本号 */
	version: string,
	/**  当前版本号 */
	current_version: string,
	/**  发布说明（`latest.json` 的 `body`，可能缺失） */
	body: string | null,
};

/**  校验报告：`missing` 与 `mismatched` 均为空即就绪 */
export type VerifyReport = {
	/**  模型 id */
	id: string,
	/**  校验结论 */
	status: ModelStatus,
	/**  缺失的必需文件（相对包顶层目录） */
	missing: string[],
	/**  大小不符的必需文件（相对包顶层目录） */
	mismatched: string[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

